const data = msg.payload;
if (!data || !data.vaga_id) {
    return [null, null];
}

const ocupada = data.ocupada === true;

const updateMsg = { payload: data, params: [ocupada, data.vaga_id] };
const insertMsg = { payload: data, params: [data.vaga_id, ocupada] };

return [updateMsg, insertMsg];

const rows = msg.payload || [];
const total = rows.length;
const ocupadas = rows.filter(r => r.ocupada).length;
const livres = total - ocupadas;
const taxa = total ? Math.round((ocupadas / total) * 1000) / 10 : 0;

const porAndar = {};
rows.forEach(r => {
    porAndar[r.andar] = porAndar[r.andar] || { total: 0, ocupadas: 0, livres: 0 };
    porAndar[r.andar].total++;
    if (r.ocupada) porAndar[r.andar].ocupadas++; else porAndar[r.andar].livres++;
});

const resumo = {
    livres, ocupadas, total,
    taxa_ocupacao: taxa,
    por_andar: porAndar,
    atualizado_em: new Date().toISOString()
};

const preferenciaisOcupadas = rows.filter(r => r.preferencial && r.ocupada).map(r => r.id);

let alerta = null;
if (total > 0 && livres === 0) {
    alerta = { nivel: "critico", mensagem: "LOTADO", timestamp: new Date().toISOString() };
} else if (preferenciaisOcupadas.length > 0) {
    alerta = { nivel: "atencao", mensagem: "Alerta: Vaga PCD ocupada sem autorização!", vagas: preferenciaisOcupadas, timestamp: new Date().toISOString() };
}

return [{ payload: resumo }, alerta ? { payload: alerta } : null];

const ids = ["A01","A02","A03","A04","A05","B01","B02","B03","B04","B05","C01","C02","C03","C04","C05"];
const id = ids[Math.floor(Math.random() * ids.length)];
msg.params = [id];
return msg;

const row = (msg.payload || [])[0];
if (!row) return null;

const novoEstado = !row.ocupada;
msg.payload = JSON.stringify({
    vaga_id: row.id,
    ocupada: novoEstado,
    preferencial: row.preferencial,
    andar: row.andar
});
return msg;

const vagaId = msg.payload && msg.payload.vaga_id;

if (!vagaId) {
    msg.statusCode = 400;
    msg.payload = { error: "vaga_id é obrigatório" };
    return [null, msg];
}

msg.params = [vagaId];
return [msg, null];

try {
    const fs = global.get('fs');
    const html = fs.readFileSync('/data/web/index.html', 'utf8');
    msg.payload = html;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
} catch (e) {
    msg.statusCode = 500;
    msg.payload = 'Erro ao carregar portal: ' + e.message;
}
return msg;
